/* ─── FOOTER ─── */
footer { background: var(--black); padding: 80px 0 40px; }
.footer-inner { display: grid; grid-template-columns: 1.8fr 1fr 1fr 1fr 1fr; gap: 40px; margin-bottom: 60px; }
