.footer-social { display: flex; gap: 12px; }
.footer-social a { width: 36px; height: 36px; border-radius: 8px; background: rgba(255,255,255,0.08); display: flex; align-items: center; justify-content: center; transition: all var(--transition); }
.footer-social a:hover { background: var(--lime); }
.footer-social a svg { width: 16px; height: 16px; stroke: rgba(255,255,255,0.6); }
.footer-social a:hover svg { stroke: var(--black); }
.footer-col h4 { color: var(--white); font-family: var(--font-display); font-size: 0.85rem; font-weight: 700; letter-spacing: 0.05em; margin-bottom: 16px; }
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-col ul li a { font-size: 0.875rem; color: rgba(255,255,255,0.45); transition: color var(--transition); }
.footer-col ul li a:hover { color: var(--lime); }
