/* ─── SPOTLIGHT ─── */
.spotlight-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.spotlight-card { background: var(--black); border-radius: var(--radius-lg); padding: 36px; color: var(--white); }
.spotlight-emoji { font-size: 2.5rem; margin-bottom: 16px; }
.spotlight-card h3 { color: var(--white); margin-bottom: 12px; font-size: 1.2rem; }
.spotlight-card p { color: rgba(255,255,255,0.6); font-size: 0.95rem; }

/* ─── RESOURCES ─── */
.resources-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.resource-card { background: var(--white); border-radius: var(--radius-lg); padding: 32px; border: 2px solid var(--gray-200); transition: all var(--transition); }
.resource-card:hover { border-color: var(--lime); transform: translateY(-4px); box-shadow: var(--shadow-md); }
.resource-tag { display: inline-block; font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; background: var(--lime); color: var(--black); padding: 3px 10px; border-radius: 4px; margin-bottom: 16px; }
.resource-card h3 { font-size: 1.05rem; margin-bottom: 12px; }
.resource-card p { font-size: 0.9rem; }
.resource-link { margin-top: 20px; font-family: var(--font-display); font-size: 0.85rem; font-weight: 700; color: var(--black); display: inline-flex; align-items: center; gap: 4px; }

/* ─── FILE TYPES ─── */
.file-types-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
.file-type { background: var(--white); border: 2px solid var(--gray-200); border-radius: var(--radius-md); padding: 24px; text-align: center; transition: all var(--transition); }
