  .nav-mobile.open { display: flex; }
  .nav-mobile a { display: block; font-family: var(--font-display); font-size: 1rem; font-weight: 600; color: var(--gray-800); padding: 12px 16px; border-radius: 10px; }
  .nav-mobile a:hover { background: var(--gray-100); }
  .nav-mobile .btn { margin-top: 8px; display: block; text-align: center; }
  .why-tabs { flex-direction: column; }
  .why-tab { min-width: unset; }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
  .ai-grid { grid-template-columns: 1fr; }
  .feature-cards { grid-template-columns: 1fr; }
  .tools-categories { grid-template-columns: 1fr 1fr; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
  .pricing-grid { grid-template-columns: 1fr; }
  .preview-enrolled { grid-template-columns: 1fr; }
  .preview-stats { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .hero-ctas { flex-direction: column; align-items: stretch; }
  .hero-ctas .btn { text-align: center; justify-content: center; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-categories { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr; }
}

/* ─── PRODUCT DEMO ─── */
.product-demo { background: var(--off-white); }
.demo-accordion { background: var(--white); border-radius: var(--radius-xl); border: 2px solid var(--gray-200); overflow: hidden; }
.demo-header { display: flex; align-items: center; justify-content: space-between; padding: 28px 36px; cursor: pointer; }
.demo-header h3 { font-size: 1.2rem; }
