}
.hero-inner { position: relative; z-index: 2; }
.hero-badge { display: inline-flex; align-items: center; gap: 8px; background: rgba(230,255,50,0.12); border: 1px solid rgba(230,255,50,0.25); color: var(--lime); font-family: var(--font-display); font-size: 0.8rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; padding: 8px 16px; border-radius: 100px; margin-bottom: 28px; }
.hero h1 { color: var(--white); margin-bottom: 24px; max-width: 14ch; }
.hero h1 em { font-style: normal; color: var(--lime); }
.hero-sub { font-size: 1.2rem; color: rgba(255,255,255,0.7); max-width: 560px; margin-bottom: 40px; }
.hero-ctas { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; margin-bottom: 60px; }

/* Tab Preview */
.hero-tabs { display: flex; gap: 4px; background: rgba(255,255,255,0.08); padding: 4px; border-radius: 12px; margin-bottom: 24px; width: fit-content; }
.hero-tab { font-family: var(--font-display); font-size: 0.9rem; font-weight: 600; padding: 10px 20px; border-radius: 9px; cursor: pointer; border: none; background: transparent; color: rgba(255,255,255,0.6); transition: all var(--transition); }
.hero-tab.active { background: var(--lime); color: var(--black); }
.hero-preview { border-radius: var(--radius-lg); overflow: hidden; border: 2px solid rgba(255,255,255,0.1); background: rgba(255,255,255,0.05); transition: all var(--transition); }
.hero-preview-content { display: none; padding: 32px; }
.hero-preview-content.active { display: block; }
.preview-mockup { background: var(--white); border-radius: var(--radius-md); padding: 24px; color: var(--black); }
.preview-mockup-bar { display: flex; gap: 8px; margin-bottom: 16px; }
.preview-dot { width: 10px; height: 10px; border-radius: 50%; }
.preview-dot:nth-child(1) { background: #FF5F57; }
.preview-dot:nth-child(2) { background: #FFBD2E; }
.preview-dot:nth-child(3) { background: #28CA41; }
.preview-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 16px; }
.preview-stat { background: var(--off-white); border-radius: var(--radius-sm); padding: 16px; }
.preview-stat-num { font-family: var(--font-display); font-size: 1.5rem; font-weight: 800; color: var(--black); }
