.product-card h3 { margin-bottom: 12px; }
.product-card p { margin-bottom: 20px; }
.product-link { font-family: var(--font-display); font-size: 0.9rem; font-weight: 700; color: var(--black); display: inline-flex; align-items: center; gap: 6px; }
