.product-card:hover .product-link svg { transform: translateX(4px); }

/* ─── WHY CHOOSE US ─── */
.why-choose { background: var(--white); }
.why-tabs { display: flex; gap: 4px; flex-wrap: wrap; background: var(--gray-100); padding: 4px; border-radius: 14px; margin-bottom: 48px; }
.why-tab { flex: 1; min-width: 180px; font-family: var(--font-display); font-size: 0.85rem; font-weight: 700; padding: 12px 16px; border-radius: 10px; border: none; background: transparent; color: var(--gray-600); cursor: pointer; transition: all var(--transition); text-align: center; }
.why-tab.active { background: var(--white); color: var(--black); box-shadow: var(--shadow-sm); }
.why-panel { display: none; }
.why-panel.active { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
.why-features { display: flex; flex-direction: column; gap: 16px; }
.why-feature { display: flex; gap: 16px; align-items: flex-start; padding: 20px; background: var(--off-white); border-radius: var(--radius-md); transition: all var(--transition); }
.why-feature:hover { background: var(--gray-100); }
.why-feature-icon { width: 36px; height: 36px; background: var(--lime); border-radius: 8px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.why-feature-icon svg { width: 18px; height: 18px; stroke: var(--black); }
.why-feature h4 { margin-bottom: 4px; }
.why-feature p { font-size: 0.9rem; }
.why-visual { background: var(--black); border-radius: var(--radius-xl); padding: 48px; display: flex; flex-direction: column; justify-content: center; min-height: 360px; position: relative; overflow: hidden; }
.why-visual::before { content: ''; position: absolute; top: -60px; right: -60px; width: 200px; height: 200px; background: var(--lime); border-radius: 50%; opacity: 0.15; filter: blur(40px); }
.why-visual-title { font-family: var(--font-display); font-size: 1.8rem; font-weight: 800; color: var(--white); margin-bottom: 24px; line-height: 1.2; }
.why-visual-chips { display: flex; flex-wrap: wrap; gap: 10px; }
.why-chip { background: rgba(230,255,50,0.12); border: 1px solid rgba(230,255,50,0.25); color: var(--lime); font-family: var(--font-display); font-size: 0.8rem; font-weight: 600; padding: 8px 14px; border-radius: 100px; }

/* ─── GLOBAL SCALE ─── */
.global-scale { background: var(--black); color: var(--white); }
.global-scale .section-header h2 { color: var(--white); }
.global-scale .section-header p { color: rgba(255,255,255,0.6); }
.globe-wrap { background: rgba(255,255,255,0.05); border-radius: var(--radius-xl); padding: 60px; text-align: center; border: 1px solid rgba(255,255,255,0.1); }
.globe-svg { width: 100%; max-width: 500px; }
.globe-dots { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 48px; }
.globe-dot { text-align: center; }
.globe-dot-marker { width: 12px; height: 12px; background: var(--lime); border-radius: 50%; margin: 0 auto 8px; box-shadow: 0 0 16px rgba(230,255,50,0.6); }
.globe-dot-name { font-family: var(--font-display); font-size: 0.85rem; font-weight: 600; color: var(--white); }
.globe-dot-count { font-size: 0.75rem; color: rgba(255,255,255,0.5); }

/* ─── AI AUTOMATIONS ─── */
.ai-section { background: var(--off-white); }
.ai-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.ai-card { background: var(--white); border-radius: var(--radius-lg); padding: 32px; border: 2px solid var(--gray-200); transition: all var(--transition); }
.ai-card:hover { border-color: var(--lime); transform: translateY(-4px); box-shadow: var(--shadow-md); }
.ai-card-icon { width: 48px; height: 48px; background: var(--black); border-radius: 12px; display: flex; align-items: center; justify-content: center; margin-bottom: 20px; }
.ai-card-icon svg { width: 22px; height: 22px; stroke: var(--lime); }
.ai-card h3 { font-size: 1.1rem; margin-bottom: 10px; }
.ai-tag { display: inline-block; font-size: 0.7rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; background: var(--lime); color: var(--black); padding: 3px 8px; border-radius: 4px; margin-bottom: 12px; }

/* ─── TESTIMONIALS ─── */
.testimonials { background: var(--white); }
.testimonials-carousel { position: relative; }
.testimonials-track { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.testimonial-card { background: var(--off-white); border-radius: var(--radius-lg); padding: 32px; border: 2px solid transparent; transition: all var(--transition); display: flex; flex-direction: column; }
.testimonial-card:hover { border-color: var(--lime); box-shadow: var(--shadow-md); }
.testimonial-quote { font-size: 2.5rem; color: var(--lime); font-family: serif; line-height: 1; margin-bottom: 12px; }
.testimonial-label { font-family: var(--font-display); font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--gray-400); margin-bottom: 8px; }
.testimonial-title { font-family: var(--font-display); font-size: 1.2rem; font-weight: 800; margin-bottom: 16px; }
.testimonial-text { font-size: 0.95rem; color: var(--gray-600); flex: 1; }
.testimonial-author { margin-top: 24px; padding-top: 20px; border-top: 1px solid var(--gray-200); display: flex; align-items: center; gap: 12px; }
.testimonial-avatar { width: 40px; height: 40px; border-radius: 50%; background: var(--black); display: flex; align-items: center; justify-content: center; font-family: var(--font-display); font-size: 0.85rem; font-weight: 800; color: var(--lime); flex-shrink: 0; }
.testimonial-name { font-family: var(--font-display); font-weight: 700; font-size: 0.9rem; }
.testimonial-org { font-size: 0.8rem; color: var(--gray-400); }
.carousel-controls { display: flex; align-items: center; justify-content: center; gap: 12px; margin-top: 36px; }
.carousel-btn { width: 44px; height: 44px; border-radius: 50%; border: 2px solid var(--gray-200); background: var(--white); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all var(--transition); }
.carousel-btn:hover { border-color: var(--black); background: var(--black); }
.carousel-btn:hover svg { stroke: var(--white); }
.carousel-btn svg { width: 18px; height: 18px; stroke: var(--black); }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--gray-200); cursor: pointer; transition: all var(--transition); border: none; padding: 0; }
.carousel-dot.active { background: var(--black); width: 24px; border-radius: 4px; }

/* ─── PRICING ─── */
.pricing { background: var(--off-white); }
.pricing-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-bottom: 32px; }
.pricing-card { background: var(--white); border-radius: var(--radius-lg); padding: 32px; border: 2px solid var(--gray-200); transition: all var(--transition); position: relative; }
.pricing-card.popular { border-color: var(--lime); background: var(--black); color: var(--white); }
.pricing-card.popular .pricing-price { color: var(--lime); }
.pricing-badge { position: absolute; top: -12px; left: 50%; transform: translateX(-50%); background: var(--lime); color: var(--black); font-family: var(--font-display); font-size: 0.7rem; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; padding: 4px 12px; border-radius: 100px; white-space: nowrap; }
.pricing-tier { font-family: var(--font-display); font-size: 0.8rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--gray-400); margin-bottom: 12px; }
.pricing-card.popular .pricing-tier { color: rgba(255,255,255,0.5); }
.pricing-price { font-family: var(--font-display); font-size: 2.4rem; font-weight: 800; margin-bottom: 4px; line-height: 1; }
.pricing-period { font-size: 0.85rem; color: var(--gray-400); margin-bottom: 20px; }
.pricing-card.popular .pricing-period { color: rgba(255,255,255,0.5); }
.pricing-fee { font-size: 0.8rem; font-weight: 600; color: var(--gray-600); margin-bottom: 24px; padding: 8px 12px; background: var(--off-white); border-radius: 8px; }
.pricing-card.popular .pricing-fee { background: rgba(255,255,255,0.1); color: rgba(255,255,255,0.8); }
.pricing-features { list-style: none; display: flex; flex-direction: column; gap: 10px; margin-bottom: 28px; }
.pricing-features li { display: flex; align-items: flex-start; gap: 8px; font-size: 0.88rem; color: var(--gray-600); }
.pricing-card.popular .pricing-features li { color: rgba(255,255,255,0.8); }
.pricing-features li::before { content: '✓'; font-weight: 800; color: var(--lime); flex-shrink: 0; margin-top: 1px; }
.pricing-card.popular .pricing-features li::before { color: var(--lime); }
.pricing-enterprise { background: var(--black); border-radius: var(--radius-lg); padding: 40px; display: flex; align-items: center; justify-content: space-between; gap: 32px; }
.pricing-enterprise h3 { color: var(--white); margin-bottom: 8px; }
.pricing-enterprise p { color: rgba(255,255,255,0.6); max-width: 500px; }

/* ─── INTEGRATIONS ─── */
.integrations { background: var(--white); }
.integrations-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; }
.integration-item { background: var(--off-white); border-radius: var(--radius-md); padding: 20px 16px; text-align: center; border: 2px solid transparent; transition: all var(--transition); }
.integration-item:hover { border-color: var(--lime); background: var(--white); box-shadow: var(--shadow-sm); }
.integration-logo { width: 40px; height: 40px; margin: 0 auto 10px; display: flex; align-items: center; justify-content: center; }
.integration-logo svg { width: 36px; height: 36px; }
.integration-name { font-family: var(--font-display); font-size: 0.8rem; font-weight: 700; color: var(--gray-800); }

/* ─── SOCIAL PROOF ─── */
.social-proof { background: var(--black); padding: 64px 0; }
.social-proof-inner { text-align: center; }
.social-proof h3 { color: var(--white); font-size: 1.4rem; margin-bottom: 32px; }
.sp-logos { display: flex; align-items: center; justify-content: center; gap: 40px; flex-wrap: wrap; }
.sp-logo { font-family: var(--font-display); font-size: 1.2rem; font-weight: 800; color: rgba(255,255,255,0.3); letter-spacing: -0.02em; transition: color var(--transition); }
.sp-logo:hover { color: rgba(255,255,255,0.7); }

/* ─── FAQ ─── */
.faq { background: var(--off-white); }
.faq-list { display: flex; flex-direction: column; gap: 12px; max-width: 760px; margin: 0 auto; }
.faq-item { background: var(--white); border-radius: var(--radius-md); border: 2px solid var(--gray-200); overflow: hidden; transition: border-color var(--transition); }
.faq-item.open { border-color: var(--lime); }
.faq-question { display: flex; align-items: center; justify-content: space-between; padding: 24px 28px; cursor: pointer; gap: 16px; }
.faq-question h4 { font-size: 1rem; font-weight: 700; }
.faq-icon { width: 28px; height: 28px; border-radius: 50%; background: var(--gray-100); display: flex; align-items: center; justify-content: center; flex-shrink: 0; transition: all var(--transition); }
.faq-item.open .faq-icon { background: var(--lime); transform: rotate(45deg); }
.faq-icon svg { width: 14px; height: 14px; stroke: var(--black); }
