.faq-item.open .faq-answer { max-height: 400px; padding-bottom: 24px; }
.faq-answer p { color: var(--gray-600); }

/* ─── CTA BANNER ─── */
.cta-banner { background: var(--lime); padding: 80px 0; }
.cta-banner-inner { display: flex; align-items: center; justify-content: space-between; gap: 40px; }
.cta-banner h2 { font-size: clamp(1.8rem, 3.5vw, 2.8rem); color: var(--black); max-width: 560px; }
.cta-banner p { color: rgba(0,0,0,0.6); margin-top: 12px; font-size: 1rem; }
.cta-banner-actions { display: flex; gap: 12px; flex-wrap: wrap; flex-shrink: 0; }

/* ─── FOOTER ─── */
footer { background: var(--black); padding: 80px 0 40px; }
.footer-inner { display: grid; grid-template-columns: 1.8fr 1fr 1fr 1fr 1fr; gap: 40px; margin-bottom: 60px; }
.footer-brand h3 { color: var(--white); font-family: var(--font-display); font-size: 1.4rem; font-weight: 800; margin-bottom: 12px; }
.footer-brand p { font-size: 0.9rem; color: rgba(255,255,255,0.45); line-height: 1.6; margin-bottom: 24px; }
.footer-social { display: flex; gap: 12px; }
.footer-social a { width: 36px; height: 36px; border-radius: 8px; background: rgba(255,255,255,0.08); display: flex; align-items: center; justify-content: center; transition: all var(--transition); }
.footer-social a:hover { background: var(--lime); }
.footer-social a svg { width: 16px; height: 16px; stroke: rgba(255,255,255,0.6); }
.footer-social a:hover svg { stroke: var(--black); }
.footer-col h4 { color: var(--white); font-family: var(--font-display); font-size: 0.85rem; font-weight: 700; letter-spacing: 0.05em; margin-bottom: 16px; }
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-col ul li a { font-size: 0.875rem; color: rgba(255,255,255,0.45); transition: color var(--transition); }
.footer-col ul li a:hover { color: var(--lime); }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.08); padding-top: 32px; display: flex; align-items: center; justify-content: space-between; }
.footer-bottom p { font-size: 0.85rem; color: rgba(255,255,255,0.3); }
.footer-bottom-links { display: flex; gap: 20px; }
.footer-bottom-links a { font-size: 0.85rem; color: rgba(255,255,255,0.3); transition: color var(--transition); }
.footer-bottom-links a:hover { color: var(--lime); }

/* ─── FEATURE CARDS ─── */
.feature-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.feature-card { border-radius: var(--radius-lg); padding: 36px; background: var(--white); border: 2px solid var(--gray-200); transition: all var(--transition); }
.feature-card:hover { border-color: var(--lime); box-shadow: var(--shadow-md); transform: translateY(-4px); }
.feature-card-icon { width: 52px; height: 52px; border-radius: var(--radius-sm); background: var(--black); display: flex; align-items: center; justify-content: center; margin-bottom: 20px; }
.feature-card-icon svg { width: 24px; height: 24px; stroke: var(--lime); }
.feature-card h3 { margin-bottom: 12px; }
.feature-card p { font-size: 0.95rem; }

/* ─── TOOLS GRID ─── */
.tools-section { background: var(--black); }
.tools-section .section-header h2 { color: var(--white); }
.tools-section .section-header p { color: rgba(255,255,255,0.6); }
.tools-categories { display: grid; grid-template-columns: repeat(5, 1fr); gap: 24px; }
.tool-cat { background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); border-radius: var(--radius-md); padding: 24px; }
.tool-cat-title { font-family: var(--font-display); font-size: 0.75rem; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; color: var(--lime); margin-bottom: 16px; }
.tool-cat ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.tool-cat ul li { font-size: 0.875rem; color: rgba(255,255,255,0.7); display: flex; align-items: center; gap: 6px; }
.tool-cat ul li::before { content: '→'; color: var(--lime); font-size: 0.8rem; }

/* ─── STEPS ─── */
.steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.step { text-align: center; padding: 40px; background: var(--white); border-radius: var(--radius-lg); border: 2px solid var(--gray-200); position: relative; }
.step-num { font-family: var(--font-display); font-size: 4rem; font-weight: 800; color: var(--lime); line-height: 1; margin-bottom: 16px; }
.step h3 { margin-bottom: 12px; }
.step p { font-size: 0.95rem; }

/* ─── SPOTLIGHT ─── */
.spotlight-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.spotlight-card { background: var(--black); border-radius: var(--radius-lg); padding: 36px; color: var(--white); }
.spotlight-emoji { font-size: 2.5rem; margin-bottom: 16px; }
.spotlight-card h3 { color: var(--white); margin-bottom: 12px; font-size: 1.2rem; }
.spotlight-card p { color: rgba(255,255,255,0.6); font-size: 0.95rem; }

/* ─── RESOURCES ─── */
.resources-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.resource-card { background: var(--white); border-radius: var(--radius-lg); padding: 32px; border: 2px solid var(--gray-200); transition: all var(--transition); }
.resource-card:hover { border-color: var(--lime); transform: translateY(-4px); box-shadow: var(--shadow-md); }
.resource-tag { display: inline-block; font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; background: var(--lime); color: var(--black); padding: 3px 10px; border-radius: 4px; margin-bottom: 16px; }
.resource-card h3 { font-size: 1.05rem; margin-bottom: 12px; }
.resource-card p { font-size: 0.9rem; }
.resource-link { margin-top: 20px; font-family: var(--font-display); font-size: 0.85rem; font-weight: 700; color: var(--black); display: inline-flex; align-items: center; gap: 4px; }

/* ─── FILE TYPES ─── */
.file-types-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
.file-type { background: var(--white); border: 2px solid var(--gray-200); border-radius: var(--radius-md); padding: 24px; text-align: center; transition: all var(--transition); }
.file-type:hover { border-color: var(--lime); }
.file-type-icon { font-size: 2rem; margin-bottom: 12px; }
.file-type-name { font-family: var(--font-display); font-size: 0.9rem; font-weight: 700; }

/* ─── SCROLL ANIMATIONS ─── */
.reveal { opacity: 0; transform: translateY(32px); transition: opacity 0.6s ease, transform 0.6s ease; }
.reveal.visible { opacity: 1; transform: translateY(0); }
.reveal-delay-1 { transition-delay: 0.1s; }
.reveal-delay-2 { transition-delay: 0.2s; }
.reveal-delay-3 { transition-delay: 0.3s; }
.reveal-delay-4 { transition-delay: 0.4s; }

/* ─── MEMBERSHIP SPECIFIC ─── */
.membership-why { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.membership-why-card { background: var(--white); border-radius: var(--radius-lg); padding: 36px; border: 2px solid var(--gray-200); text-align: center; transition: all var(--transition); }
.membership-why-card:hover { border-color: var(--lime); transform: translateY(-4px); box-shadow: var(--shadow-md); }
.membership-why-card .stat-num { font-size: 2.5rem; color: var(--black); }
.membership-why-card h3 { margin-bottom: 12px; }

/* ─── PAGE HERO VARIANT ─── */
.hero-page { padding-top: 160px; padding-bottom: 96px; background: var(--black); color: var(--white); position: relative; overflow: hidden; }
.hero-page::before { content: ''; position: absolute; top: -200px; right: -200px; width: 600px; height: 600px; background: var(--burgundy); border-radius: 50%; opacity: 0.15; filter: blur(80px); }
.hero-page::after { content: ''; position: absolute; bottom: -100px; left: -100px; width: 400px; height: 400px; background: var(--lime); border-radius: 50%; opacity: 0.08; filter: blur(60px); }
.hero-page .container { position: relative; z-index: 2; text-align: center; max-width: 820px; }
.hero-page h1 { color: var(--white); margin-bottom: 24px; }
.hero-page .hero-sub { margin: 0 auto 40px; text-align: center; max-width: 600px; }
.hero-page .hero-ctas { justify-content: center; }

/* ─── MOBILE ─── */
@media (max-width: 1100px) {
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
  .tools-categories { grid-template-columns: repeat(3, 1fr); }
  .footer-inner { grid-template-columns: 1fr 1fr; }
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 900px) {
  section { padding: 72px 0; }
  .products-grid { grid-template-columns: 1fr; }
  .why-panel.active { grid-template-columns: 1fr; }
  .feature-cards { grid-template-columns: 1fr 1fr; }
  .stats-bar-inner { grid-template-columns: 1fr; gap: 24px; }
  .testimonials-track { grid-template-columns: 1fr; }
  .cta-banner-inner { flex-direction: column; text-align: center; }
  .pricing-enterprise { flex-direction: column; text-align: center; }
  .steps { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .membership-why { grid-template-columns: 1fr; }
  .file-types-grid { grid-template-columns: repeat(2, 1fr); }
  .globe-dots { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  h1 { font-size: 2.4rem; }
  h2 { font-size: 1.8rem; }
  .nav-links { display: none; }
  .nav-hamburger { display: block; }
  .nav-mobile { display: none; position: fixed; top: 72px; left: 0; right: 0; background: var(--white); border-bottom: 1px solid var(--gray-200); padding: 16px 24px; z-index: 99; flex-direction: column; gap: 4px; }
  .nav-mobile.open { display: flex; }
  .nav-mobile a { display: block; font-family: var(--font-display); font-size: 1rem; font-weight: 600; color: var(--gray-800); padding: 12px 16px; border-radius: 10px; }
  .nav-mobile a:hover { background: var(--gray-100); }
  .nav-mobile .btn { margin-top: 8px; display: block; text-align: center; }
  .why-tabs { flex-direction: column; }
  .why-tab { min-width: unset; }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
  .ai-grid { grid-template-columns: 1fr; }
  .feature-cards { grid-template-columns: 1fr; }
  .tools-categories { grid-template-columns: 1fr 1fr; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
  .pricing-grid { grid-template-columns: 1fr; }
  .preview-enrolled { grid-template-columns: 1fr; }
  .preview-stats { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .hero-ctas { flex-direction: column; align-items: stretch; }
  .hero-ctas .btn { text-align: center; justify-content: center; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-categories { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr; }
}

/* ─── PRODUCT DEMO ─── */
.product-demo { background: var(--off-white); }
.demo-accordion { background: var(--white); border-radius: var(--radius-xl); border: 2px solid var(--gray-200); overflow: hidden; }
.demo-header { display: flex; align-items: center; justify-content: space-between; padding: 28px 36px; cursor: pointer; }
.demo-header h3 { font-size: 1.2rem; }
.demo-toggle { width: 36px; height: 36px; border-radius: 50%; background: var(--black); display: flex; align-items: center; justify-content: center; transition: transform var(--transition); }
.demo-toggle svg { width: 16px; height: 16px; stroke: var(--lime); }
.demo-content { max-height: 0; overflow: hidden; transition: max-height 0.4s ease; }
.demo-content.open { max-height: 600px; }
.demo-inner { padding: 0 36px 36px; }
.demo-mockup { background: var(--off-white); border-radius: var(--radius-lg); padding: 32px; }
.demo-mockup-title { font-family: var(--font-display); font-weight: 800; font-size: 1.1rem; margin-bottom: 20px; }
.demo-progress { display: flex; flex-direction: column; gap: 14px; }
.demo-progress-item { display: flex; align-items: center; gap: 14px; }
.demo-progress-label { font-family: var(--font-display); font-size: 0.85rem; font-weight: 600; min-width: 160px; }
.demo-bar { flex: 1; height: 8px; background: var(--gray-200); border-radius: 4px; overflow: hidden; }
.demo-fill { height: 100%; background: var(--lime); border-radius: 4px; }
.demo-val { font-family: var(--font-display); font-size: 0.85rem; font-weight: 700; min-width: 44px; text-align: right; }

